test_that("fn_fmls<- and fn_fmls_names<- change formals", {
  fn <- function() NULL
  fn_fmls(fn) <- list(a = 1)
  expect_identical(fn_fmls(fn), pairlist(a = 1))

  fn_fmls_names(fn) <- c("b")
  expect_identical(fn_fmls(fn), pairlist(b = 1))
})

test_that("fn_ functions requires closures", {
  msg <- "must be an R function, not a primitive function"
  expect_error(fn_fmls(`+`), msg)
  expect_error(fn_fmls_names(`+`), msg)
  expect_error(fn_fmls_syms(`+`), msg)
  expect_error(fn_fmls(`+`) <- list(a = 1, b = 2), msg)
  expect_error(fn_fmls_names(`+`) <- c("A", "B"), msg)
})

test_that("assignment methods preserve attributes", {
  orig <- structure(function(foo) NULL, foo = "foo", bar = "bar")

  fn <- orig
  fn_fmls(fn) <- list(arg = 1)
  expect_identical(attributes(fn), attributes(orig))

  fn <- orig
  fn_fmls_names(fn) <- "bar"
  expect_identical(attributes(fn), attributes(orig))

  fn <- orig
  fn_body(fn) <- "body"
  orig_attrs <- attributes(orig)
  orig_attrs$srcref <- NULL
  expect_identical(attributes(fn), orig_attrs)
})

test_that("fn_body() requires a closure to extract body", {
  expect_error(fn_body(c), "`fn` must be an R function")
  expect_equal(
    fn_body(function() {
      NULL
    }),
    quote({
      NULL
    })
  )
  expect_equal(
    fn_body(function() NULL),
    quote({
      NULL
    })
  )
})

test_that("fn_env() requires a function to extract env", {
  expect_error(fn_env(1L), "`fn` must be a function")
  expect_identical(fn_env(function() NULL), current_env())
})

test_that("`fn_env<-`() sets environment", {
  fn <- function() NULL
  fn_env(fn) <- base_env()
  expect_reference(fn_env(fn), base_env())
})

test_that("primitive predicates work", {
  expect_true(is_primitive_eager(c))
  expect_true(is_primitive_lazy(`$`))
  expect_false(is_primitive_eager(`$`))
  expect_false(is_primitive_lazy(`c`))
})

test_that("quosures converted to functions ignore their arguments", {
  fn <- as_function(quo("foo"))
  expect_no_error(expect_identical(fn(NULL), "foo"))
})

test_that("as_function() supports nested quosures", {
  quo <- local({
    lhs <- "quux"
    rhs <- local({
      rhs <- "hunoz"
      quo(rhs)
    })
    quo(paste(lhs, !!rhs))
  })

  fn <- as_function(quo)
  expect_identical(fn(), "quux hunoz")
})

test_that("fn_body() always returns a `{` block", {
  expect_equal(
    fn_body(function() "foo"),
    quote({
      "foo"
    })
  )
})

test_that("as_function() adds a class to lambda functions", {
  out <- as_function(~foo)
  expect_s3_class(out, c("rlang_lambda_function", "function"))
  expect_output(print(out), "<lambda>")
})

test_that("fn_env() returns base namespace for primitives", {
  expect_reference(fn_env(base::list), ns_env("base"))
})

test_that("as_closure() wrappers dispatch properly", {
  local_bindings(
    .env = global_env(),
    as.character.foobar = function(...) "dispatched!"
  )
  x <- structure(list(), class = "foobar")
  expect_identical(as_closure(as.character)(x), "dispatched!")
})

test_that("as_closure() wrappers are not masked", {
  wrapper <- as_closure(as.character)
  as.character <- function(...) abort("tilt")
  expect_identical(wrapper(1), "1")

  wrapper <- as_closure(as.character)
  expect_error(wrapper(1), "tilt")
})

test_that("arguments of closured primitives are matched by name before `...` (tidyverse/purrr#411)", {
  expect_false(as_closure(isS4)("foo"))
})

test_that("arguments of closured primitives are matched by name after `...`", {
  fn <- as_closure(min)
  expect_true(is_na(fn(1, NA)))
  expect_identical(fn(na.rm = TRUE, 1, NA), 1)
})

test_that("transforming defused formula to function causes an informative error (#953)", {
  expect_error(as_function(quote(~foo)), "must carry an environment")
})

test_that("functions created from quosures with as_function() print properly", {
  fn <- as_function(quo(x))
  expect_equal(body(fn), quote(x))
})

test_that("as_function() creates functions that respect visibility", {
  f <- as_function(quo(invisible(1)))
  expect_invisible(f())

  f <- as_function(quo(1))
  expect_visible(f())

  f <- as_function(~ invisible(1))
  expect_invisible(f())

  f <- as_function(~1)
  expect_visible(f())
})

test_that("as_function() with a quosure can be serialised", {
  fn <- as_function(local({
    a <- 10
    quo(a)
  }))
  blob <- serialize(fn, NULL)
  expect_equal(
    eval_tidy(fn),
    eval_tidy(unserialize(blob)),
    ignore_function_env = TRUE
  )
})

test_that("as_function() fetches from the global env", {
  foo <- function() NULL
  local_bindings(
    .env = global_env(),
    foo = function() "foo"
  )
  expect_equal(as_function("foo")(), "foo")
})

test_that("as_function() has nice errors", {
  my_function <- function(my_arg) {
    as_function(my_arg)
  }

  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    as_function(1)

    as_function(1, arg = "foo")

    my_function(1 + 2)

    my_function(1)

    my_function(a ~ b)
  })
})

test_that("check inputs in function accessors", {
  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    fn_fmls(1)
    fn_body(1)
    fn_env(1)
  })
})

test_that("closure wrapper of seq.int() works (#1468)", {
  seq_int <- as_closure(seq.int)
  expect_equal(seq_int(1), 1)
  expect_equal(seq_int(1, 2), 1:2)
  expect_equal(seq_int(1, 2, 2), 1)
})


# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-formula.R ---
# Creation ----------------------------------------------------------------

test_that("is_formula works", {
  expect_true(is_formula(~10))
  expect_false(is_formula(10))
})


# Getters -----------------------------------------------------------------

test_that("throws errors for bad inputs", {
  expect_error(f_rhs(1), "must be a formula")
  expect_error(f_rhs(`~`()), "Invalid formula")
  expect_error(f_rhs(`~`(1, 2, 3)), "Invalid formula")

  expect_error(f_lhs(1), "must be a formula")
  expect_error(f_lhs(`~`()), "Invalid formula")
  expect_error(f_lhs(`~`(1, 2, 3)), "Invalid formula")

  expect_error(f_env(1), "must be a formula")
})

test_that("extracts call, name, or scalar", {
  expect_identical(f_rhs(~x), quote(x))
  expect_identical(f_rhs(~ f()), quote(f()))
  expect_identical(f_rhs(~1L), 1L)
})


# Setters -----------------------------------------------------------------

test_that("can replace RHS of one-sided formula", {
  f <- ~x1
  f_rhs(f) <- quote(x2)

  expect_equal(f, ~x2)
})

test_that("can replace both sides of two-sided formula", {
  f <- x1 ~ y1
  f_lhs(f) <- quote(x2)
  f_rhs(f) <- quote(y2)

  expect_equal(f, x2 ~ y2)
})

test_that("can remove lhs of two-sided formula", {
  f <- x ~ y
  f_lhs(f) <- NULL

  expect_equal(f, ~y)
})

test_that("can modify environment", {
  f <- x ~ y
  env <- new.env()
  f_env(f) <- env

  expect_equal(f_env(f), env)
})

test_that("setting RHS preserves attributes", {
  attrs <- list(foo = "bar", class = "formula")

  f <- inject(structure(~foo, !!!attrs))
  f_rhs(f) <- quote(bar)

  expect_identical(f, inject(structure(~bar, !!!attrs)))
})

test_that("setting LHS preserves attributes", {
  attrs <- list(foo = "bar", class = "formula")

  f <- inject(structure(~foo, !!!attrs))
  f_lhs(f) <- quote(bar)

  expect_identical(f, inject(structure(bar ~ foo, !!!attrs)))

  f_lhs(f) <- quote(baz)
  expect_identical(f, inject(structure(baz ~ foo, !!!attrs)))
})

test_that("setting environment preserves attributes", {
  attrs <- list(foo = "bar", class = "formula")
  env <- env()

  f <- inject(structure(~foo, !!!attrs))
  f_env(f) <- env
  expect_identical(f, inject(structure(~foo, !!!attrs, .Environment = env)))
})

test_that("unevaluated tilde calls are formulas", {
  f <- quote(~foo)
  expect_true(is_formula(f))
  expect_false(is_formula(f, scoped = TRUE))
  expect_true(is_formula(f, scoped = FALSE))
  expect_true(is_formula(f, scoped = NULL))

  expect_false(is_bare_formula(f))
  expect_false(is_bare_formula(f, scoped = TRUE))
  expect_true(is_bare_formula(f, scoped = FALSE))
  expect_true(is_bare_formula(f, scoped = NULL))
})


# Utils --------------------------------------------------------------

test_that("quosures are not recognised as bare formulas", {
  expect_false(is_bare_formula(quo(foo)))
})

test_that("lhs is inspected", {
  expect_true(is_formula(~foo))

  expect_false(is_formula(~foo, lhs = TRUE))
  expect_true(is_formula(~foo, lhs = FALSE))

  expect_true(is_formula(foo ~ bar, lhs = TRUE))
  expect_false(is_formula(foo ~ bar, lhs = FALSE))
})


# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-friendly-type.R ---
test_that("obj_type_friendly() supports objects", {
  expect_equal(
    friendly_types(mtcars),
    c(
      object = "a <data.frame> object",
      object_no_value = "a <data.frame> object",
      vector = "a data frame",
      vector_length = "a data frame"
    )
  )
  expect_true(all(
    friendly_types(quo(1), vector = FALSE) == "a <quosure> object"
  ))
})

test_that("obj_type_friendly() only displays the first class of objects", {
  x <- structure(1, class = c("subclass", "class"))
  expect_identical(obj_type_friendly(x), "a <subclass> object")
})

test_that("obj_type_friendly() supports matrices and arrays (#141)", {
  # 1D, 2D, and >=3D all vary!

  expect_true(all(friendly_types(array(list(1, 2, 3))) == "a list 1D array"))
  expect_true(all(friendly_types(matrix(list(1, 2, 3))) == "a list matrix"))
  expect_true(all(
    friendly_types(array(list(1, 2, 3), dim = 1:3)) == "a list 3D array"
  ))

  expect_true(all(friendly_types(array(1:3)) == "an integer 1D array"))
  expect_true(all(friendly_types(matrix(1:3)) == "an integer matrix"))
  expect_true(all(
    friendly_types(array(1:3, dim = 1:3)) == "an integer 3D array"
  ))

  expect_true(all(
    friendly_types(array(letters[1:3])) == "a character 1D array"
  ))
  expect_true(all(friendly_types(matrix(letters[1:3])) == "a character matrix"))
  expect_true(all(
    friendly_types(array(letters[1:3], dim = 1:3)) == "a character 3D array"
  ))
})

test_that("obj_type_friendly() supports missing arguments", {
  expect_equal(obj_type_friendly(missing_arg()), "absent")
})

test_that("obj_type_friendly() handles scalars", {
  expect_equal(
    friendly_types(NA),
    c(
      object = "`NA`",
      object_no_value = "`NA`",
      vector = "a logical vector",
      vector_length = "a logical vector of length 1"
    )
  )
  expect_equal(
    friendly_types(na_int),
    c(
      object = "an integer `NA`",
      object_no_value = "an integer `NA`",
      vector = "an integer vector",
      vector_length = "an integer vector of length 1"
    )
  )
  expect_equal(
    friendly_types(na_dbl),
    c(
      object = "a numeric `NA`",
      object_no_value = "a numeric `NA`",
      vector = "a double vector",
      vector_length = "a double vector of length 1"
    )
  )
  expect_equal(
    friendly_types(na_cpl),
    c(
      object = "a complex `NA`",
      object_no_value = "a complex `NA`",
      vector = "a complex vector",
      vector_length = "a complex vector of length 1"
    )
  )
  expect_equal(
    friendly_types(na_chr),
    c(
      object = "a character `NA`",
      object_no_value = "a character `NA`",
      vector = "a character vector",
      vector_length = "a character vector of length 1"
    )
  )

  expect_equal(
    friendly_types(TRUE),
    c(
      object = "`TRUE`",
      object_no_value = "a logical value",
      vector = "a logical vector",
      vector_length = "a logical vector of length 1"
    )
  )
  expect_equal(
    friendly_types(FALSE),
    c(
      object = "`FALSE`",
      object_no_value = "a logical value",
      vector = "a logical vector",
      vector_length = "a logical vector of length 1"
    )
  )

  expect_equal(
    friendly_types(1L),
    c(
      object = "the number 1",
      object_no_value = "an integer",
      vector = "an integer vector",
      vector_length = "an integer vector of length 1"
    )
  )
  expect_equal(
    friendly_types(1.0),
    c(
      object = "the number 1",
      object_no_value = "a number",
      vector = "a double vector",
      vector_length = "a double vector of length 1"
    )
  )
  expect_equal(
    friendly_types(1i),
    c(
      object = "the complex number 0+1i",
      object_no_value = "a complex number",
      vector = "a complex vector",
      vector_length = "a complex vector of length 1"
    )
  )
  expect_equal(
    friendly_types(as.raw(1)),
    c(
      object = "the raw value 01",
      object_no_value = "a raw value",
      vector = "a raw vector",
      vector_length = "a raw vector of length 1"
    )
  )

  expect_equal(
    friendly_types("foo"),
    c(
      object = "the string \"foo\"",
      object_no_value = "a string",
      vector = "a character vector",
      vector_length = "a character vector of length 1"
    )
  )
  expect_equal(
    friendly_types(""),
    c(
      object = "the empty string \"\"",
      object_no_value = "\"\"",
      vector = "a character vector",
      vector_length = "a character vector of length 1"
    )
  )

  expect_equal(
    friendly_types(list(1)),
    c(
      object = "a list",
      object_no_value = "a list",
      vector = "a list",
      vector_length = "a list of length 1"
    )
  )
  expect_setequal(friendly_types(matrix(NA)), "a logical matrix")
  expect_setequal(friendly_types(matrix(1)), "a double matrix")
})

