# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-hash.R ---
test_that("simple hashes with no ALTREP and no attributes are reproducible", {
  skip_if_big_endian()
  expect_identical(hash(1), "a3f7d4a39b65b170005aafbbeed05106")
  expect_identical(hash("a"), "4d52a7da68952b85f039e85a90f9bbd2")
  expect_identical(hash(1:5 + 0L), "0d26bf75943b8e13c080c6bab12a7440")
})

test_that("hash_file() errors if the file doesn't exist", {
  expect_error(hash_file("foo.ext"))
})

test_that("hash_file() works for 0 length input", {
  expect_identical(hash_file(character()), character())
})

test_that("hash_file() has known fixed value for empty files", {
  skip_if_big_endian()

  path <- withr::local_tempfile()
  file.create(path)

  expect_identical(hash_file(path), "99aa06d3014798d86001c324468d497f")
})

test_that("hash_file() results change as more data is written to the file", {
  path <- withr::local_tempfile()
  file.create(path)

  initial <- hash_file(path)

  saveRDS(1, path)

  expect_true(hash_file(path) != initial)
})

test_that("hash_file()'s internal state is reset between files", {
  path1 <- withr::local_tempfile()
  file.create(path1)
  saveRDS(1, path1)

  path2 <- withr::local_tempfile()
  file.create(path2)
  saveRDS(2, path2)

  hashes <- hash_file(c(path1, path2))

  expect_identical(hashes[[1]], hash_file(path1))
  expect_identical(hashes[[2]], hash_file(path2))
})


# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-lifecycle.R ---
test_that("deprecate_soft() warns when called from global env", {
  reset_warning_verbosity("rlang_test1")
  reset_warning_verbosity("rlang_test2")
  reset_warning_verbosity("rlang_test3")
  reset_warning_verbosity("rlang_test4")

  # Disable testthat handling
  withr::local_envvar(c("TESTTHAT_PKG" = ""))

  depr_soft <- function(id) deprecate_soft("foo", id)
  depr <- function(id) deprecate_warn("foo", id)

  # Indirect usage
  local_env <- env(
    ns_env("rlang"),
    depr_soft = depr_soft,
    depr = depr
  )
  local(envir = local_env, {
    expect_no_warning(depr_soft("rlang_test1"))
    expect_warning(depr("rlang_test2"), "foo")

    # Does not warn again
    expect_no_warning(depr("rlang_test2"))
  })

  # Direct usage
  local_bindings(
    .env = global_env(),
    depr_soft = depr_soft,
    depr = depr
  )
  local(envir = global_env(), {
    expect_warning(depr_soft("rlang_test3"), "foo")
    expect_warning(depr("rlang_test4"), "foo")

    # Warns again
    expect_warning(depr_soft("rlang_test3"), "foo")
    expect_warning(depr("rlang_test4"), "foo")
  })
})

test_that("deprecate_soft() warns when called from package being tested", {
  reset_warning_verbosity("rlang_test")

  withr::local_envvar(c("TESTTHAT_PKG" = "rlang"))
  depr <- function() {
    deprecate_soft("warns from package being tested", id = "rlang_test")
  }
  expect_warning(depr(), "warns from")
  expect_warning(depr(), "warns from")
})

test_that("deprecate_soft() indirect behaviour when warning verbosity is set", {
  reset_warning_verbosity("rlang_test")

  local_options(lifecycle_verbosity = "warning")

  local_env <- env(
    ns_env("base"),
    depr = inject(function(id) (!!deprecate_soft)("foo", id))
  )

  # FIXME: Is this a bug in lifecycle?
  local(envir = local_env, {
    expect_no_warning(depr("rlang_test"))
    expect_no_warning(depr("rlang_test"))
  })
})

test_that("can disable lifecycle warnings", {
  local_lifecycle_silence()
  expect_no_warning(deprecate_soft("foo"))
  expect_no_warning(deprecate_warn("foo"))
})

test_that("can promote lifecycle warnings to errors", {
  local_lifecycle_errors()
  expect_defunct(deprecate_soft("foo"), "foo")
  expect_defunct(deprecate_warn("foo"), "foo")
})

test_that("can enable warnings and errors with `with_` helpers", {
  expect_defunct(with_lifecycle_errors(deprecate_soft("foo")), "foo")
  expect_no_warning(with_lifecycle_warnings(with_lifecycle_silence(deprecate_warn(
    "foo"
  ))))

  # FIXME: Is this a bug in lifecycle?
  expect_no_warning(with_lifecycle_warnings(deprecate_soft("foo")))
})

test_that("soft-deprecation warnings are issued when called from child of global env as well", {
  fn <- function() deprecate_soft("called from child of global env")
  expect_warning(eval_bare(call2(fn), env(global_env())), "child of global env")
})

test_that("once-per-session note is not displayed on repeated warnings", {
  reset_warning_verbosity("once-per-session-note")

  wrn <- catch_cnd(
    deprecate_warn("foo", "once-per-session-note"),
    "lifecycle_warning_deprecated"
  )
  expect_true(grepl("once every", conditionMessage(wrn)))
})

test_that("lifecycle signallers support character vectors", {
  local_lifecycle_errors()
  expect_defunct(deprecate_soft(c("foo", "bar")), "foo\nbar")
  expect_defunct(deprecate_warn(c("foo", "bar")), "foo\nbar")
  expect_defunct(deprecate_stop(c("foo", "bar")), "foo\nbar")
})

test_that("the topenv of the empty env is not the global env", {
  expect_silent(deprecate_soft("topenv empty env", user_env = empty_env()))
})

test_that("can supply bullets", {
  expect_snapshot({
    deprecate_warn(c("foo", "i" = "bar"))
  })
})


# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-names.R ---
local_options(rlib_message_verbosity = "quiet")

test_that("unique_names() handles unnamed vectors", {
  expect_equal(names_as_unique(names2(1:3)), c("...1", "...2", "...3"))
})

test_that("names_as_unique() is a no-op when no repairs are needed", {
  x <- c("x", "y")
  out <- names_as_unique(x)
  expect_true(is_reference(out, x))
  expect_equal(out, c("x", "y"))
})

test_that("names_as_unique() eliminates emptiness and duplication", {
  expect_equal(
    names_as_unique(c("", "x", "y", "x")),
    c("...1", "x...2", "y", "x...4")
  )
  expect_equal(
    names_as_unique(c("1", "foo", "1")),
    c("1...1", "foo", "1...3")
  )
})

test_that("names_as_unique(): solo empty or NA gets suffix", {
  expect_equal(names_as_unique(""), "...1")
  expect_equal(names_as_unique(NA_character_), "...1")
})

test_that("names_as_unique() treats ellipsis like empty string", {
  expect_equal(names_as_unique("..."), names_as_unique(""))
})

test_that("two_three_dots() does its job and no more", {
  two_to_three_dots <- function(names) {
    sub("(^[.][.][1-9][0-9]*$)", ".\\1", names)
  }

  x <- c(".", ".1", "...1", "..1a")
  expect_equal(two_to_three_dots(x), x)

  expect_equal(two_to_three_dots(c("..1", "..22")), c("...1", "...22"))
})

test_that("two dots then number treated like three dots then number", {
  expect_equal(names_as_unique("..2"), names_as_unique("...5"))
})

test_that("names_as_unique() strips positional suffixes, re-applies as needed", {
  x <- c("...20", "a...1", "b", "", "a...2...34")
  expect_equal(names_as_unique(x), c("...1", "a...2", "b", "...4", "a...5"))

  expect_equal(names_as_unique("a...1"), "a")
  expect_equal(names_as_unique(c("a...2", "a")), c("a...1", "a...2"))
  expect_equal(
    names_as_unique(c("a...3", "a", "a")),
    c("a...1", "a...2", "a...3")
  )
  expect_equal(
    names_as_unique(c("a...2", "a", "a")),
    c("a...1", "a...2", "a...3")
  )
  expect_equal(
    names_as_unique(c("a...2", "a...2", "a...2")),
    c("a...1", "a...2", "a...3")
  )
})

test_that("names_as_unique() is idempotent", {
  x <- c("...20", "a...1", "b", "", "a...2")
  expect_equal(names_as_unique(!!x), names_as_unique(names_as_unique(!!x)))
})

test_that("unique-ification has an 'algebraic'-y property", {
  x <- c("...20", "a...1", "b", "", "a...2", "d")
  y <- c("", "a...3", "b", "...3", "e")

  ## Fix names on each, catenate, fix the whole
  z1 <- names_as_unique(c(names_as_unique(x), names_as_unique(y)))

  ## Fix names on x, catenate, fix the whole
  z2 <- names_as_unique(c(names_as_unique(x), y))

  ## Fix names on y, catenate, fix the whole
  z3 <- names_as_unique(c(x, names_as_unique(y)))

  ## Catenate, fix the whole
  z4 <- names_as_unique(c(x, y))

  expect_equal(z1, z2)
  expect_equal(z1, z3)
  expect_equal(z1, z4)
})

test_that("names_as_unique() are verbose or silent", {
  local_options(rlib_message_verbosity = "default")
  expect_message(names_as_unique(c("", "")), "-> `...1`", fixed = TRUE)
  expect_message(regexp = NA, names_as_unique(c("", ""), quiet = TRUE))
})

test_that("names with only duplicates are repaired", {
  expect_equal(names_as_unique(c("x", "x")), c("x...1", "x...2"))
})

test_that("names_as_unique() handles encodings", {
  x <- unname(unlist(encodings()[c("utf8", "latin1")]))
  out <- names_as_unique(x)
  expect_equal(out, paste0(rep(x[[1]], 2), "...", 1:2))
  expect_equal(Encoding(out), c("UTF-8", "UTF-8"))
})

test_that("names_inform_repair() signals classed messages", {
  local_options(rlib_message_verbosity = "default")
  expect_message(
    names_inform_repair("x", "y"),
    class = "rlib_message_name_repair"
  )
})

test_that("names_inform_repair() can be silenced by `rlib_name_repair_verbosity`", {
  local_options(
    rlib_message_verbosity = "default",
    rlib_name_repair_verbosity = "quiet"
  )
  expect_message(names_inform_repair("x", "y"), NA)
})

test_that("`rlib_name_repair_verbosity` is validated", {
  local_options(rlib_name_repair_verbosity = 1)
  expect_error(peek_name_repair_verbosity())

  local_options(rlib_name_repair_verbosity = "qu")
  expect_error(peek_name_repair_verbosity())
})


# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-node.R ---
test_that("node() creates a pairlist node", {
  x <- new_node("foo", "bar")
  expect_type(x, "pairlist")
  expect_identical(node_car(x), "foo")
  expect_identical(node_cdr(x), "bar")
})

test_that("node getters and pokers work", {
  A <- as.pairlist(c(a = "a", b = "b"))
  B <- as.pairlist(c(A = "A", B = "B"))
  x <- pairlist(foo = A, bar = B, baz = "baz")

  expect_identical(node_car(x), A)
  expect_identical(node_cdr(x), pairlist(bar = B, baz = "baz"))
  expect_identical(node_caar(x), "a")
  expect_identical(node_cadr(x), B)
  expect_identical(node_cdar(x), pairlist(b = "b"))
  expect_identical(node_cddr(x), pairlist(baz = "baz"))
  expect_identical(node_tag(x), sym("foo"))

  node_poke_car(x, B)
  expect_identical(node_car(x), B)

  node_poke_cdr(x, pairlist(foo = A))
  expect_identical(node_cdr(x), pairlist(foo = A))

  node_poke_cdar(x, "cdar")
  expect_identical(node_cdar(x), "cdar")

  node_poke_caar(x, "caar")
  expect_identical(node_caar(x), "caar")

  node_poke_cadr(x, "cadr")
  expect_identical(node_cadr(x), "cadr")

  node_poke_cddr(x, "cddr")
  expect_identical(node_cddr(x), "cddr")

  node_poke_tag(x, sym("tag"))
  expect_identical(node_tag(x), sym("tag"))
})

test_that("node_tree_clone() clones all nodes", {
  x <- pairlist(1, pairlist(2))
  clone <- node_tree_clone(x)

  # Outer vector
  expect_false(obj_address(x) == obj_address(clone))

  # Outer node list
  expect_true(obj_address(node_car(x)) == obj_address(node_car(clone)))

  cdr <- node_cdr(x)
  clone_cdr <- node_cdr(clone)
  expect_false(obj_address(cdr) == obj_address(clone_cdr))

  # Inner node list
  cadr <- node_car(cdr)
  clone_cadr <- node_car(clone_cdr)
  expect_false(obj_address(cadr) == obj_address(clone_cadr))

  # Inner vector
  caadr <- node_car(cadr)
  clone_caadr <- node_car(clone_cadr)
  expect_true(obj_address(caadr) == obj_address(clone_caadr))
})

test_that("pairlist predicates detect pairlists", {
  node <- new_node(NULL)
  call <- quote(foo(bar))

  expect_true(is_pairlist(node))

  expect_true(is_node(node))
  expect_true(is_node(call))

  expect_true(is_node_list(node))
  expect_true(is_node_list(NULL))
})

test_that("pairlist2() converts to pairlist", {
  expect_identical_(pairlist2(1, !!!c(2, 3), 4), pairlist(1, 2, 3, 4))
  expect_identical_(
    pairlist2(1, !!!mtcars[1:2], 4),
    pairlist(1, mpg = mtcars$mpg, cyl = mtcars$cyl, 4)
  )

  local_bindings(.env = global_env(), `[[.rlang_foobar` = function(x, i) "foo")
  foobar <- structure(NA, class = "rlang_foobar")
  expect_identical_(pairlist2(1, !!!foobar, 4), pairlist(1, "foo", 4))
})

test_that("pairlist2() duplicates spliced pairlists", {
  x <- pairlist("foo", "bar")
  pairlist2(1, !!!x, 4)
  expect_identical(x, pairlist("foo", "bar"))
})

test_that("pairlist2() preserves empty arguments", {
  expect_identical(
    pairlist2(1, x = , , 4),
    pairlist(1, x = missing_arg(), missing_arg(), 4)
  )
})

test_that("pairlist2() supports splice boxes", {
  expect_identical(
    pairlist2(1, splice(list("foo", "bar")), 4),
    pairlist(1, "foo", "bar", 4)
  )
})

test_that("pairlist2() supports empty spliced vectors", {
  expect_null_(pairlist2(!!!NULL))
  expect_null_(pairlist2(!!!lgl()))
  expect_null_(pairlist2(!!!list()))
})


# --- FILE: https://raw.githubusercontent.com/r-lib/rlang/main/tests/testthat/test-nse-defuse.R ---
test_that("quos() creates quosures", {
  fs <- quos(x = 1 + 2, y = 2 + 3)
  expect_identical(fs$x, as_quosure(~ 1 + 2))
  expect_identical(fs$y, as_quosure(~ 2 + 3))
})

test_that("quos() captures correct environment", {
  fn <- function(x = a + b, ...) {
    list(dots = quos(x = x, y = a + b, ...), env = environment())
  }
  out <- fn(z = a + b)

  expect_identical(get_env(out$dots$x), out$env)
  expect_identical(get_env(out$dots$y), out$env)
  expect_identical(get_env(out$dots$z), current_env())
})

test_that("dots are interpolated", {
  fn <- function(...) {
    baz <- "baz"
    fn_var <- quo(baz)
    g(..., toupper(!!fn_var))
  }
  g <- function(...) {
    foo <- "foo"
    g_var <- quo(foo)
    h(toupper(!!g_var), ...)
  }
  h <- function(...) {
    quos(...)
  }

  bar <- "bar"
  var <- quo(bar)
  dots <- fn(toupper(!!var))

  expect_identical(
    map(dots, deparse),
    named_list("~toupper(~foo)", "~toupper(~bar)", "~toupper(~baz)")
  )
  expect_identical(map(dots, eval_tidy), named_list("FOO", "BAR", "BAZ"))
})

test_that("dots capture is stack-consistent", {
  fn <- function(...) {
    g(quos(...))
  }
  g <- function(dots) {
    h(dots, foo(bar))
  }
  h <- function(dots, ...) {
    dots
  }
  expect_identical(fn(foo(baz)), quos_list(quo(foo(baz))))
})

test_that("dots can be spliced in", {
  fn <- function(...) {
    var <- "var"
    list(
      out = g(!!!quos(...), bar(baz), !!!list(a = var, b = ~foo)),
      env = current_env()
    )
  }
  g <- function(...) {
    quos(...)
  }

  out <- fn(foo(bar))
  expected <- quos_list(
    quo(foo(bar)),
    set_env(quo(bar(baz)), out$env),
    a = quo("var"),
    b = set_env(quo(!!with_env(out$env, ~foo)), out$env)
  )
  expect_identical(out$out, expected)
})

test_that("spliced dots are wrapped in formulas", {
  args <- alist(x = var, y = foo(bar))
  expect_identical(quos(!!!args), quos_list(x = quo(var), y = quo(foo(bar))))
})

test_that("dot names are interpolated", {
  var <- "baz"
  expect_identical(
    quos(!!var := foo, !!toupper(var) := bar),
    quos_list(baz = quo(foo), BAZ = quo(bar))
  )
  expect_identical(quos(!!var := foo, bar), quos_list(baz = quo(foo), quo(bar)))

  var <- quote(baz)
  expect_identical(quos(!!var := foo), quos_list(baz = quo(foo)))
})

test_that("corner cases are handled when interpolating dot names", {
  var <- na_chr
  expect_identical(names(quos(!!var := NULL)), "NA")

  var <- NULL
  expect_snapshot({
    (expect_error(quos(!!var := NULL)))
    (expect_error(list2(!!c("a", "b") := NULL)))
  })
})

test_that("dots are forwarded to named arguments", {
  outer <- function(...) inner(...)
  inner <- function(...) fn(...)
  fn <- function(x) enquo(x)

  env <- child_env(current_env())
  expect_identical(
    with_env(env, outer(foo(bar))),
    new_quosure(quote(foo(bar)), env)
  )
})

test_that("pronouns are scoped throughout nested captures", {
  outer <- function(data, ...) eval_tidy(quos(...)[[1]], data = data)
  inner <- function(...) map(quos(...), eval_tidy)

  data <- list(foo = "bar", baz = "baz")
  baz <- "bazz"

  expect_identical(
    outer(data, inner(foo, baz)),
    set_names(list("bar", "baz"), c("", ""))
  )
})

test_that("Can supply := with LHS even if .named = TRUE", {
  expect_warning(
    regexp = NA,
    expect_identical(
      quos(!!"nm" := 2, .named = TRUE),
      quos_list(nm = as_quosure(quote(2), empty_env()))
    )
  )
})

test_that("Can't supply both `=` and `:=`", {
  expect_error(regexp = "both `=` and `:=`", quos(foobar = !!"nm" := 2))
  expect_error(
    regexp = "both `=` and `:=`",
    quos(foobar = !!"nm" := 2, .named = TRUE)
  )
})

test_that("RHS of tidy defs are unquoted", {
  expect_identical(
    quos(foo := !!"bar"),
    quos_list(foo = as_quosure(quote("bar"), empty_env()))
  )
})

test_that("can capture empty list of dots", {
  fn <- function(...) quos(...)
  expect_identical(fn(), quos_list())
})

test_that("quosures are spliced before serialisation", {
  quosures <- quos(!!quo(foo(!!quo(bar))), .named = TRUE)
  expect_identical(names(quosures), "foo(bar)")
})

test_that("missing arguments are captured", {
  q <- quo()
  expect_true(is_missing(quo_get_expr(q)))
  expect_identical(quo_get_env(q), empty_env())
})

test_that("empty quosures are forwarded", {
  inner <- function(x) enquo(x)
  outer <- function(x) inner(!!enquo(x))
  expect_identical(outer(), quo())
})

test_that("quos() captures missing arguments", {
  expect_identical(
    quos(,, .ignore_empty = "none"),
    quos_list(quo(), quo()),
    c("", "")
  )
})

test_that("quos() ignores missing arguments", {
  expect_identical(
    quos(,, "foo", ),
    quos_list(quo(), quo(), new_quosure("foo", empty_env()))
  )
  expect_identical(
    quos(,, "foo", , .ignore_empty = "all"),
    quos_list(new_quosure("foo", empty_env()))
  )
})

test_that("quosured literals are forwarded as is", {
  expect_identical(quo(!!quo(NULL)), new_quosure(NULL, empty_env()))
  expect_identical(
    quos(!!quo(10L)),
    set_names(quos_list(new_quosure(10L, empty_env())), "")
  )
})

test_that("expr() returns missing argument", {
  expect_true(is_missing(expr()))
})

test_that("expr() supports forwarded arguments", {
  fn <- function(...) g(...)
  g <- function(...) expr(...)
  expect_identical(fn(foo), quote(foo))
})

test_that("can take forced arguments", {
  fn <- function(allow, x) {
    force(x)
    captureArgInfo(x)
  }
  expect_identical(fn(TRUE, letters), list(expr = letters, env = empty_env()))

  if (getRversion() < "3.2.0") {
    skip("lapply() does not force arguments in R 3.1")
  }
  expect_error(lapply(1:2, captureArgInfo), "must be an argument name")

  args <- list(
    list(expr = 1L, env = empty_env()),
    list(expr = 2L, env = empty_env())
  )
  expect_identical(lapply(1:2, function(x) captureArgInfo(x)), args)
})

test_that("capturing an argument that doesn't exist fails", {
  fn <- function(x) captureArgInfo(`_foobar`)
  expect_error(fn(), "object '_foobar' not found")

  fn <- function() enquo(`_foobar`)
  expect_error(fn(), "not found")

  fn <- function() enexpr(`_foobar`)
  expect_error(fn(), "not found")

  expect_error((function() rlang::enexpr(`_foobar`))(), "not found")
})

test_that("can capture arguments across ancestry", {
  y <- "foo"
  fn <- function() captureArgInfo(y)
  expect_identical(fn(), list(expr = "foo", env = empty_env()))
})

test_that("can capture arguments that do exist", {
  fn <- function() {
    x <- 10L
    captureArgInfo(x)
  }
  expect_identical(fn(), list(expr = 10L, env = empty_env()))
})

test_that("can capture missing argument", {
  expect_identical(
    captureArgInfo(),
    list(expr = missing_arg(), env = empty_env())
  )
})

test_that("serialised unicode in `:=` LHS is unserialised", {
  skip_if_no_utf8_marker()
  nms <- with_latin1_locale({
    exprs <- exprs("\u5e78" := 10)
    names(exprs)
  })
  expect_identical(charToRaw(nms), charToRaw("\u5e78"))
})

test_that("exprs() supports auto-naming", {
  expect_identical(
    exprs(foo(bar), b = baz(), .named = TRUE),
    list(`foo(bar)` = quote(foo(bar)), b = quote(baz()))
  )
})

test_that("dots_interp() supports unquoting", {
  expect_identical(exprs(!!(1 + 2)), named_list(3))
  expect_identical(exprs(!!(1 + 1) + 2), named_list(quote(2 + 2)))
  expect_identical(exprs(!!(1 + 1) + 2 + 3), named_list(quote(2 + 2 + 3)))
  expect_identical(exprs(!!"foo" := bar), named_list(foo = quote(bar)))
})

test_that("dots_interp() has no side effect", {
